            let mut tMins: vec3_t = [-3.0, -3.0, -3.0];
            let mut tMaxs: vec3_t = [3.0, 3.0, 3.0];
            let mut trajDif: vec3_t = [0.0; 3];
            let mut gbmAngles: vec3_t = [0.0; 3];
            let mut boneOrg: vec3_t = [0.0; 3];
            let mut projectedBoneOrg: vec3_t = [0.0; 3];
